#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_autop;
uniform float amzp_aSpeed;
uniform float amzp_progress;
uniform float amzp_scale;
uniform float amzp_angle;
uniform float2 amzp_position;
uniform float2 amzp_stretch;
uniform float amzp_alpha;
uniform float amzp_hardness;
uniform float amzp_blendMode;
uniform float amzp_alphaComp;
uniform float amzp_numPts;
uniform float amzp_ptSize;
uniform float amzp_shape;
uniform float amzp_randRot;
uniform float amzp_shapeSpin;
uniform float amzp_spread;
uniform float amzp_rotSpd;
uniform float amzp_oriX;
uniform float amzp_oriY;
uniform float amzp_oriZ;
uniform float amzp_camZ;
uniform float amzp_focus;
uniform float amzp_aperture;
uniform float amzp_blurAmt;
uniform float amzp_flickF;
uniform float amzp_flickA;
uniform float amzp_seed;
uniform float amzp_colMode;
layout(color) uniform half4 amzp_single;
layout(color) uniform half4 amzp_c1;
layout(color) uniform half4 amzp_c2;
layout(color) uniform half4 amzp_c3;
layout(color) uniform half4 amzp_c4;
layout(color) uniform half4 amzp_c5;
uniform float amzp_hueRot;
uniform float amzp_gradMap;
uniform float amzp_gmTri;
layout(color) uniform half4 amzp_gmFg;
layout(color) uniform half4 amzp_gmMid;
layout(color) uniform half4 amzp_gmBg;
uniform float amzp_quality;
uniform float amzp_overdrawOn;
    const float NMCUT = 0.04;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float4 layerAt(float2 uv) { return (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float TT() { return (amzp_autop>0.5) ? amzp_progress + time * amzp_aSpeed : amzp_progress; }
    float2 nmRot(float2 q, float a) { float c = cos(a), s = sin(a); return float2(c * q.x - s * q.y, s * q.x + c * q.y); }
    float nmZ() { return max(amzp_scale * 2.0, 0.002); }
    float2 nmStd(float2 p, float pxsc) {
        p -= amzp_position * pxsc;
        p = nmRot(p, -radians(amzp_angle));
        return p / (nmZ() * max(amzp_stretch, float2(0.01)));
    }
    float2 stdFC() {
        float2 W = layer;
        float2 q = amzLayerNorm() * W - 0.5 * W;
        q.y = -q.y;
        q = nmStd(q, pxs());
        q.y = -q.y;
        return q + 0.5 * W;
    }
    float4 nmGradMap(float4 fx) {
        if (!(amzp_gradMap>0.5)) return fx;
        float3 un = fx.a > 0.0001 ? fx.rgb / fx.a : float3(0.0);
        float v = clamp(fx.a * (0.25 + 0.75 * dot(un, float3(0.299, 0.587, 0.114))), 0.0, 1.0);
        float4 pB = float4(amzp_gmBg.rgb * amzp_gmBg.a, amzp_gmBg.a), pM = float4(amzp_gmMid.rgb * amzp_gmMid.a, amzp_gmMid.a), pF = float4(amzp_gmFg.rgb * amzp_gmFg.a, amzp_gmFg.a);
        float4 c = (amzp_gmTri>0.5) ? (v < 0.5 ? mix(pB, pM, v * 2.0) : mix(pM, pF, v * 2.0 - 1.0)) : mix(pB, pF, v);
        return c;
    }
    float4 nmBlend(float4 tex, float4 fx) {
        float4 fr = clamp(fx * amzp_hardness, 0.0, 64.0) * clamp(amzp_alpha, 0.0, 1.0);
        float4 f = clamp(fx * amzp_hardness, 0.0, 1.0) * clamp(amzp_alpha, 0.0, 1.0);
        float4 b = tex * clamp(amzp_alphaComp, 0.0, 1.0);
        float4 o;
        if (int(amzp_blendMode) == 0) {
            float na = clamp((f.a - NMCUT) / (1.0 - NMCUT), 0.0, 1.0);
            o = float4(f.rgb * (na / max(f.a, 0.0001)), na);
        }
        else if (int(amzp_blendMode) == 1) o = float4(b.rgb * (f.rgb + (1.0 - f.a)), b.a);
        else if (int(amzp_blendMode) == 2) o = float4(b.rgb + f.rgb - b.rgb * f.rgb, b.a + f.a - b.a * f.a);
        else if (int(amzp_blendMode) == 4) o = float4(b.rgb + fr.rgb, max(b.a, max(f.a, max(f.r, max(f.g, f.b)))));
        else o = f + b * (1.0 - f.a);
        o = clamp(o, 0.0, 1.0);
        return float4(min(o.rgb, float3(o.a)), o.a);
    }
    float hs(float n) { return fract(sin(n) * 43758.5453); }
    float3x3 rX(float a) { float s = sin(a), c = cos(a); return float3x3(1.0, 0.0, 0.0, 0.0, c, -s, 0.0, s, c); }
    float3x3 rY(float a) { float s = sin(a), c = cos(a); return float3x3(c, 0.0, s, 0.0, 1.0, 0.0, -s, 0.0, c); }
    float3x3 rZ(float a) { float s = sin(a), c = cos(a); return float3x3(c, -s, 0.0, s, c, 0.0, 0.0, 0.0, 1.0); }
    float3 hueRotC(float3 c, float a) {
        float3 k = float3(0.57735);
        float ca = cos(a), sa = sin(a);
        return clamp(c * ca + cross(k, c) * sa + k * dot(k, c) * (1.0 - ca), 0.0, 1.0);
    }
    float3 palCol(float i) {
        float s = mod(i, 5.0);
        if (s < 1.0) return amzp_c1.rgb;
        if (s < 2.0) return amzp_c2.rgb;
        if (s < 3.0) return amzp_c3.rgb;
        if (s < 4.0) return amzp_c4.rgb;
        return amzp_c5.rgb;
    }
    float sdTri(float2 p, float r) {
        const float k = 1.7320508;
        p.x = abs(p.x) - r; p.y = p.y + r / k;
        if (p.x + k * p.y > 0.0) p = float2(p.x - k * p.y, -k * p.x - p.y) / 2.0;
        p.x -= clamp(p.x, -2.0 * r, 0.0);
        return -length(p) * sign(p.y);
    }
    float sdStar5(float2 p, float r, float rf) {
        float2 k1 = float2(0.809016994375, -0.587785252292), k2 = float2(-k1.x, k1.y);
        p.x = abs(p.x);
        p -= 2.0 * max(dot(k1, p), 0.0) * k1;
        p -= 2.0 * max(dot(k2, p), 0.0) * k2;
        p.x = abs(p.x); p.y -= r;
        float2 ba = rf * float2(-k1.y, k1.x) - float2(0.0, 1.0);
        float h = clamp(dot(p, ba) / dot(ba, ba), 0.0, r);
        return length(p - ba * h) * sign(p.y * ba.x - p.x * ba.y);
    }
    float dd2(float2 v) { return dot(v, v); }
    float sdHeart(float2 p) {
        p.x = abs(p.x);
        if (p.y + p.x > 1.0) return sqrt(dd2(p - float2(0.25, 0.75))) - 0.35355339;
        return sqrt(min(dd2(p - float2(0.0, 1.0)), dd2(p - 0.5 * max(p.x + p.y, 0.0)))) * sign(p.x - p.y);
    }
    float sdPlus(float2 p, float2 b) {
        p = abs(p); p = (p.y > p.x) ? p.yx : p.xy;
        float2 q = p - b; float k = max(q.y, q.x);
        float2 w = (k > 0.0) ? q : float2(b.y - p.x, -k);
        return sign(k) * length(max(w, 0.0));
    }
    float shapeSD(float2 q, float dn, float2 dir) {
        if (int(amzp_shape) == 0) return dn - 1.0;
        if (int(amzp_shape) == 1) { float2 d = abs(q) - 0.82; return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0); }
        if (int(amzp_shape) == 2) return (abs(q.x) + abs(q.y) - 1.05) * 0.70710678;
        if (int(amzp_shape) == 3) return sdTri(q + float2(0.0, 0.18), 0.98);
        if (int(amzp_shape) == 4) return sdStar5(q, 1.1, 0.45);
        if (int(amzp_shape) == 5) return sdHeart(q * 0.6 + float2(0.0, 0.52)) / 0.6;
        if (int(amzp_shape) == 6) return abs(length(q) - 0.8) - 0.2;
        if (int(amzp_shape) == 7) return sdPlus(q, float2(1.0, 0.3));
        float a = dot(q, dir), b = dot(q, float2(-dir.y, dir.x));
        float L = 1.9;
        float w = 0.26 * (1.0 - 0.75 * clamp(abs(a) / L, 0.0, 1.0));
        return length(float2(max(abs(a) - L, 0.0), b)) - w;
    }
    float2 shapeRotQ(float2 q, float id, float T) {
        if (int(amzp_shape) == 0 || int(amzp_shape) == 8) return q;
        float r = 0.0, s = 1.0;
        if ((amzp_randRot>0.5)) { r = hs(id * 91.7 + 3.3) * 6.28318531; s = (hs(id * 17.3 + 1.1) < 0.5 ? -1.0 : 1.0) * (0.6 + 0.8 * hs(id * 37.1 + 5.9)); }
        r += T * amzp_shapeSpin * 6.28318531 * s;
        float c = cos(r), sn = sin(r);
        return float2(c * q.x + sn * q.y, -sn * q.x + c * q.y);
    }
    int qSamples() { float q = clamp(amzp_quality, 1.0, 5.0); return q < 1.5 ? 4 : (q < 2.5 ? 8 : (q < 3.5 ? 16 : (q < 4.5 ? 24 : 32))); }
    void nmMain() {
        float2 W = layer;
        float4 orig = layerAt(amzLayerNorm());
        float2 I = stdFC();
        float T = TT();
        float2 uv = (I - 0.5 * W) / W.y;
        float t = T * amzp_rotSpd;
        float3 ro = float3(0.0, 0.0, -amzp_camZ);
        float3x3 ori = rZ(radians(amzp_oriZ)) * rY(radians(amzp_oriY)) * rX(radians(amzp_oriX));
        float tp = t - 0.05 * amzp_rotSpd;
        float3x3 rot = ori * (rZ(sin(t)) * rY(cos(t)) * rX(sin(t)));
        float3x3 rotP = ori * (rZ(sin(tp)) * rY(cos(tp)) * rX(sin(tp)));
        float3 c = float3(0.0);
        int NS = qSamples();
        float NP = clamp(floor(amzp_numPts + 0.5), 1.0, 100.0);
        float A = 0.0;
        for (int i = 0; i < 32; i++) {
            if (i >= NS) break;
            float fi = float(i);
            float an = hs(fi + 13.1) * 6.2831;
            float2 off = float2(cos(an), sin(an)) * amzp_aperture * hs(fi + 71.7);
            float3 D = -ro + float3(uv + off * amzp_blurAmt, amzp_focus);
            float3 rd = normalize(D);
            float pw = 1.0 / (W.y * nmZ() * max(min(amzp_stretch.x, amzp_stretch.y), 0.01) * length(D));
            float3 hc = float3(0.0); float ha = 0.0;
            for (int j = 0; j < 100; j++) {
                float id = float(j);
                if (id >= NP) break;
                float sd = id + amzp_seed * 101.0;
                float3 bp = float3(hs(sd * 13.37) * 2.0 - 1.0, hs(sd * 73.42) * 2.0 - 1.0, hs(sd * 31.69) * 2.0 - 1.0) * amzp_spread;
                float3 amzLocal_pos = rot * bp;
                float3 oc = amzLocal_pos - ro;
                float tc = dot(oc, rd);
                float3 v = rd * tc - oc;
                float dn = length(v) / amzp_ptSize;
                if (tc > 0.0 && dn < 2.3) {
                    float aw = max(tc * pw / amzp_ptSize, 1e-4);
                    float2 q = shapeRotQ(v.xy / amzp_ptSize, id, T);
                    float2 mv = int(amzp_shape) == 8 ? (amzLocal_pos - rotP * bp).xy : float2(1.0, 0.0);
                    mv = length(mv) > 1e-6 ? normalize(mv) : (length(amzLocal_pos.xy) > 1e-6 ? normalize(amzLocal_pos.xy) : float2(1.0, 0.0));
                    float cov = clamp(0.5 - shapeSD(q, dn, mv) / aw, 0.0, 1.0);
                    if (cov > 0.0) {
                        float fl = max(1.0 + sin(T * amzp_flickF + id * 19.19) * amzp_flickA, 0.0);
                        float3 bc = int(amzp_colMode) == 0 ? palCol(id) : amzp_single.rgb;
                        hc = mix(hc, hueRotC(bc, radians(amzp_hueRot)) * fl, cov); ha = mix(ha, 1.0, cov);
                    }
                }
            }
            c += hc; A += ha;
        }
        c /= float(NS); A /= float(NS);
        float4 G = float4(c, clamp(max(A, max(c.r, max(c.g, c.b))), 0.0, 1.0));
        amzOutput = nmBlend(orig, nmGradMap(G));
    }
    void amzRender() {
        nmMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
